# =============================================================================
# Writes reference.jl: RadiometricCamera's own thin-plate spline
# (src/camera/tps.jl, src/board/warping.jl) evaluated on fixed inputs, every
# value printed with `repr` (exact round trip). The test
# (test/thin_plate_spline_tests.jl) asks VisualGeometryToolkitCore the same
# questions and compares with `==`.
#
# Recorded from RadiometricCamera 0.2.0 at 642410fa, Julia 1.12, in that
# checkout's own environment (run from the RadiometricCamera checkout):
#
#   julia +1.12 --project=. <this file> <output path>
#
# The coefficients, nodal weights and bending energy go through `inv` and
# BLAS products, so their last bits are this machine's BLAS build's; the test
# compares them within measured bounds (TPS_BITWISE=1 for `==`), and the plain
# arithmetic after (w, a) with `==`. Do not regenerate per machine.
#
# Not discovered by the test runner (no `_tests.jl` suffix) and not run by it:
# RadiometricCamera is not a dependency of the suite.
# =============================================================================

using RadiometricCamera
using RadiometricCamera: U, ThinPlateSpline, grid_nodes, tps_coefficients, tps_evaluate, nodal_weights, bending_energy,
    Focus, board_height, board_height_grad, height_weights, HEIGHT_NODES, HEIGHT_NC
using StaticArrays: SVector

const OUT = length(ARGS) >= 1 ? ARGS[1] : joinpath(@__DIR__, "reference.jl")

# Query points in the image chart [-0.5, 0.5]²: on nodes (of both grids, of the
# 5 × 5 grid only, a corner), inside the hull, a hair off a node, just outside
# and far outside it.
const POINTS = SVector{2, Float64}[
    (0.0, 0.0), (-0.5, -0.5), (0.0, 0.5), (0.5, 0.25), (0.25, -0.5),
    (0.123, -0.377), (-0.311, 0.207), (0.4999, 0.0001), (0.05, 0.45), (-0.47, -0.12),
    (0.333, 0.333), (1.0e-9, 0.0), (-0.2, 0.71), (0.6, -0.6), (2.0, 1.5),
    (-3.7, 0.25), (10.0, -7.0), (-25.0, 30.0), (100.0, 100.0), (1000.0, -1000.0),
]
# The same questions on RadiometricCamera's height grid, the chart [0, 1]².
const HEIGHT_POINTS = SVector{2, Float64}[
    (0.5, 0.5), (0.0, 0.0), (0.25, 0.75), (1.0, 0.5), (0.75, 0.0),
    (0.623, 0.123), (0.189, 0.707), (0.9999, 0.5001), (0.55, 0.95), (0.03, 0.38),
    (0.833, 0.833), (0.5, 0.500000001), (0.3, 1.21), (1.1, -0.1), (2.5, 2.0),
    (-3.2, 0.75), (10.5, -6.5), (-24.5, 30.5), (100.5, 100.5), (1000.5, -999.5),
]

const VALUES_3 = [1 / (1.5 + 0.1 * sin(3i)) for i in 1:9]
const VALUES_5 = [0.2 * cos(0.7i) + 0.05i for i in 1:25]
const HEIGHTS = SVector{HEIGHT_NC}([0.01 * sin(1.3i) for i in 1:HEIGHT_NC])

lit(x::Float64) = repr(x)
lit(x::Float32) = repr(x)
lit(v::AbstractVector) = "[" * join(lit.(v), ", ") * "]"
lit(v::SVector{2}) = "SVector(" * lit(v[1]) * ", " * lit(v[2]) * ")"
lit(vs::AbstractVector{<:SVector{2}}) = "[\n        " * join(lit.(vs), ",\n        ") * ",\n    ]"
rows(vs) = "[\n        " * join(lit.(vs), ",\n        ") * ",\n    ]"

function grid_reference(io, name, n, values)
    tps = ThinPlateSpline(grid_nodes(n))
    w, a = tps_coefficients(tps, values)
    f32 = Focus(tps, Float32.(values))   # RC's Float32 path: Float64 solver, Float32 (nodes, w, a)
    println(io, "    $name = (")
    println(io, "        nodes = ", lit(collect(tps.nodes)), ",")
    println(io, "        values = ", lit(values), ",")
    println(io, "        w = ", lit(collect(w)), ",")
    println(io, "        a = ", lit(collect(a)), ",")
    println(io, "        evaluate = ", lit([tps_evaluate(tps, w, a, p) for p in POINTS]), ",")
    println(io, "        nodal_weights = ", rows([collect(nodal_weights(tps, p)) for p in POINTS]), ",")
    println(io, "        bending_energy = ", lit(bending_energy(tps, values)), ",")
    println(io, "        w_f32 = ", lit(collect(f32.w)), ",")
    println(io, "        a_f32 = ", lit(collect(f32.a)), ",")
    println(io, "        evaluate_f32 = ", lit([tps_evaluate(f32.nodes, f32.w, f32.a, SVector{2, Float32}(p)) for p in POINTS]), ",")
    println(io, "        radial_basis = ", rows([[U(p, q) for q in tps.nodes] for p in POINTS]), ",")
    println(io, "    ),")
    return nothing
end

open(OUT, "w") do io
    println(io, "# GENERATED by generate.jl from RadiometricCamera 0.2.0 (642410fa), Julia $(VERSION). Do not edit.")
    println(io, "const TPS_REFERENCE = (")
    println(io, "    points = ", lit(POINTS), ",")
    grid_reference(io, "grid_3", 3, VALUES_3)
    grid_reference(io, "grid_5", 5, VALUES_5)
    w = height_weights(HEIGHTS)
    println(io, "    height = (")
    println(io, "        nodes = ", lit(collect(HEIGHT_NODES)), ",")
    println(io, "        points = ", lit(HEIGHT_POINTS), ",")
    println(io, "        heights = ", lit(collect(HEIGHTS)), ",")
    println(io, "        w = ", lit(collect(w)), ",")
    println(io, "        height = ", lit([board_height(HEIGHTS, b) for b in HEIGHT_POINTS]), ",")
    println(io, "        gradient = ", lit([board_height_grad(HEIGHTS, b) for b in HEIGHT_POINTS]), ",")
    println(io, "    ),")
    println(io, ")")
end
